use clap::{Parser, ValueEnum};
use std::path::PathBuf;

#[derive(Copy, Clone, Debug, ValueEnum)]
enum Style {
    None,
    Ascii,
    Ascii2,
    Sharp,
    Rounded,
    Reinforced,
    Markdown,
    Grid,
}

impl Style {
    fn as_str(&self) -> &'static str {
        match self {
            Style::None => "none",
            Style::Ascii => "ascii",
            Style::Ascii2 => "ascii2",
            Style::Sharp => "sharp",
            Style::Rounded => "rounded",
            Style::Reinforced => "reinforced",
            Style::Markdown => "markdown",
            Style::Grid => "grid",
        }
    }
}

#[derive(Copy, Clone, Debug, ValueEnum)]
enum Align {
    Left,
    Center,
    Right,
}

#[derive(Parser, Debug)]
#[command(name = "csview", version = "1.3.4", about = "A high performance csv viewer with cjk/emoji support.", disable_help_flag = false, disable_version_flag = false)]
struct Args {
    #[arg(value_name = "FILE")]
    file: Option<PathBuf>,

    #[arg(short = 'H', long = "no-headers", help = "Specify that the input has no header row")]
    no_headers: bool,

    #[arg(short = 'n', long = "number", help = "Prepend a column of line numbers to the table")]
    number: bool,

    #[arg(short = 't', long = "tsv", help = "Use '\\t' as delimiter for tsv", conflicts_with = "delimiter")]
    tsv: bool,

    #[arg(short = 'd', long = "delimiter", value_name = "DELIMITER", default_value = ",", help = "Specify the field delimiter")]
    delimiter: char,

    #[arg(short = 's', long = "style", value_name = "STYLE", default_value = "sharp", help = "Specify the border style")]
    style: Style,

    #[arg(short = 'p', long = "padding", value_name = "PADDING", default_value_t = 1, help = "Specify padding for table cell")]
    padding: usize,

    #[arg(short = 'i', long = "indent", value_name = "INDENT", default_value_t = 0, help = "Specify global indent for table")]
    indent: usize,

    #[arg(long = "sniff", value_name = "LIMIT", default_value_t = 1000, help = "Limit column widths sniffing to the specified number of rows. Specify \"0\" to cancel limit")]
    sniff: usize,

    #[arg(long = "header-align", value_name = "HEADER_ALIGN", default_value = "center", help = "Specify the alignment of the table header")]
    header_align: Align,

    #[arg(long = "body-align", value_name = "BODY_ALIGN", default_value = "left", help = "Specify the alignment of the table body")]
    body_align: Align,

    #[arg(short = 'P', long = "disable-pager", help = "Disable pager")]
    disable_pager: bool,
}

fn display_width(s: &str) -> usize {
    use unicode_width::UnicodeWidthChar;
    s.chars().map(|c| c.width().unwrap_or(1)).sum()
}

fn truncate_by_width(s: &str, max_width: usize) -> String {
    use unicode_width::UnicodeWidthChar;
    let mut cur = 0usize;
    let mut out = String::new();
    for c in s.chars() {
        let w = c.width().unwrap_or(1);
        if cur + w > max_width {
            break;
        }
        cur += w;
        out.push(c);
    }
    out
}

fn render_cell(content: &str, col_width: usize, padding: usize, align: Align) -> String {
    let truncated = truncate_by_width(content, col_width);
    let tw = display_width(&truncated);
    let fill = if col_width >= tw { col_width - tw } else { 0 };
    let (left_fill, right_fill) = match align {
        Align::Left => (0, fill),
        Align::Right => (fill, 0),
        Align::Center => {
            let left = fill / 2;
            let right = fill - left;
            (left, right)
        }
    };
    let mut s = String::new();
    s.push_str(&" ".repeat(padding));
    s.push_str(&" ".repeat(left_fill));
    s.push_str(&truncated);
    s.push_str(&" ".repeat(right_fill));
    s.push_str(&" ".repeat(padding));
    s
}

