    // Determine delimiter
    let delim: u8 = if args.tsv { b'\t' } else { args.delimiter as u8 };

    // Read input
    let data: Vec<u8> = if let Some(path) = args.file.as_ref() {
        match std::fs::read(path) {
            Ok(b) => b,
            Err(e) => {
                eprintln!("csview: {}", e);
                std::process::exit(1);
            }
        }
    } else {
        let mut buf = Vec::new();
        use std::io::Read;
        std::io::stdin().lock().read_to_end(&mut buf).unwrap();
        buf
    };

    let data_slice: &[u8] = if data.starts_with(&[0xEF, 0xBB, 0xBF]) {
        &data[3..]
    } else {
        &data[..]
    };

    let mut rdr = csv::ReaderBuilder::new()
        .delimiter(delim)
        .has_headers(false)
        .flexible(false)
        .from_reader(data_slice);

    let mut records: Vec<Vec<String>> = Vec::new();
    for result in rdr.records() {
        match result {
            Ok(rec) => {
                records.push(rec.iter().map(|s| s.to_string()).collect());
            }
            Err(e) => {
