                std::process::exit(1);
            }
        }
    }

    // Header/body split
    let (header_opt, body): (Option<Vec<String>>, Vec<Vec<String>>) = if args.no_headers {
        if records.is_empty() {
            (None, Vec::new())
        } else {
            (None, records)
        }
    } else {
        if records.is_empty() {
            (None, Vec::new())
        } else {
            let hdr = records.remove(0);
            (Some(hdr), records)
        }
    };

