            let s = idx.to_string();
            let cw = display_width(&s);
            if cw > w {
                w = cw;
            }
        }
        // Also if no header mode and header_opt is None, the header "#" not considered? But for -n with -H, header is numbers first row? Actually header "#"? In -H -n case, header is numbers first row? Wait earlier we saw -H -n header is "1","2"... So header "#"? In -H mode, there is no header "#", first row number header is "1" ? Let's see behavior: -H -n gave first number column header "1" not "#". Wait earlier output for -H -n:
        // "┌───┬───────┬───────┬──────┐
