                // If file empty and -H -n, there are zero rows, so number column would have zero width? But maybe they still show nothing? Not crucial.
            }
            // But need at least width for numbers if body has rows.
        }
        // We'll recompute correctly.
        Some(w)
    } else {
        None
    };

    // Actually re-evaluate number width properly
    let number_width = if args.number {
        if header_opt.is_some() {
            let mut w = display_width("#");
            for idx in 1..=body.len() {
                let cw = display_width(&idx.to_string());
