                // No mid separator for zero cols? For has_header && has_body with ncols 0, would there be mid? But with zero cols, mid would be "├┤"? However if has_header && has_body with zero cols, we would have header row and body rows. Original maybe not tested. We'll ignore.
                if has_bottom {
                    out.push_str(&build_border_line(&indent_str, bottom_left, bottom_fill, bottom_join, bottom_right, &combined_interiors));
                }
                // Done zero col case
                // But need to handle ascii2/markdown not here
                // Return
                // For grid zero col, same.
                // Skip below
                // Use early return logic: we have constructed out, need to print and exit. We'll store in variable and later print.
                // To avoid duplicate logic, we will just set out and then later print via main branching.
                // However we need to differentiate for non-zero cols below. We'll handle zero cols as early return.
                // We'll just continue to printing via match result.
                // For this branch, we have out ready.
                // Need to ensure we don't also go to non-zero logic.
                // We'll handle via if ncols_total==0 { out } else { ... }
                out
            } else {
                // Non-zero cols
                // Top border
                if has_top {
                    out.push_str(&build_border_line(&indent_str, top_left, top_fill, top_join, top_right, &combined_interiors));
                }
                // Header row
                if let Some(cells) = header_cells_rendered.as_ref() {
                    let row_inner = cells.join(row_mid);
                    let line = format!("{}{}{}{}{}\n", indent_str, row_left, row_inner, row_right, "");
                    // Actually row_left + inner + row_right
                    // row_inner is cells joined by row_mid, each cell already includes padding.
                    // So line = indent + row_left + cells.join(row_mid) + row_right + "\n"
                    let mut s = String::new();
                    s.push_str(&indent_str);
                    s.push_str(row_left);
                    s.push_str(&row_inner);
                    s.push_str(row_right);
                    s.push('\n');
                    out.push_str(&s);
                }
                // Header separator if has_header && has_body
                if has_header && has_body {
                    out.push_str(&build_border_line(&indent_str, mid_left, mid_fill, mid_join, mid_right, &combined_interiors));
                }
                // Body rows
                for (idx, cells) in body_rows_rendered.iter().enumerate() {
                    let row_inner = cells.join(row_mid);
                    let mut s = String::new();
                    s.push_str(&indent_str);
                    s.push_str(row_left);
                    s.push_str(&row_inner);
                    s.push_str(row_right);
                    s.push('\n');
                    out.push_str(&s);
                    // For Grid, add separator between body rows
                    if matches!(args.style, Style::Grid) && idx + 1 < body_rows_rendered.len() {
                        out.push_str(&build_border_line(&indent_str, mid_left, mid_fill, mid_join, mid_right, &combined_interiors));
                    }
                }
                // If no header and no body but ncols_total >0 (empty file with number column)
                // That case has already a header row via header_cells_rendered synthesized, so header handled.
                // If still out only has top and no rows (should not happen as ncols_total>0 implies we had at least number column or original cols, so top was added but need row? But for empty file without number, ncols_total==0, already handled.
                // Bottom
                if has_bottom {
                    out.push_str(&build_border_line(&indent_str, bottom_left, bottom_fill, bottom_join, bottom_right, &combined_interiors));
                }
                out
            }
        }
    };

    // Output handling with pager
    if args.disable_pager {
        print!("{}", output);
    } else {
        // Check if stdout is tty
        let is_tty = unsafe { libc::isatty(libc::STDOUT_FILENO) != 0 };
        if is_tty {
            // Try to spawn pager (less -F -R -X -P ?)
            // Original likely uses `less` via `pager` crate or `minus`? Simpler to try to use `less`.
            // We'll attempt to pipe to `less -R -F -X` if available, else just print.
            use std::process::{Command, Stdio};
            let mut pager_cmd = std::env::var("PAGER").unwrap_or_else(|_| "less".to_string());
            // If PAGER is less, add options
            let mut cmd = Command::new(&pager_cmd);
            // For less, add -F -R -X
            if pager_cmd.contains("less") {
                cmd.args(&["-R", "-F", "-X"]);
            }
            cmd.stdin(Stdio::piped());
            if let Ok(mut child) = cmd.spawn() {
                if let Some(mut stdin) = child.stdin.take() {
                    use std::io::Write;
                    let _ = stdin.write_all(output.as_bytes());
                }
                let _ = child.wait();
                return;
            } else {
                print!("{}", output);
            }
        } else {
            print!("{}", output);
        }
    }
}
