use clap::{Arg, Command, value_parser};

fn display_width(s: &str) -> usize {
    use unicode_width::UnicodeWidthChar;
    s.chars().map(|c| c.width().unwrap_or(1)).sum()
}
fn truncate_by_width(s: &str, max_width: usize) -> String {
    use unicode_width::UnicodeWidthChar;
    let mut cur = 0usize;
    let mut out = String::new();
    for c in s.chars() {
        let w = c.width().unwrap_or(1);
        if cur + w > max_width {
            break;
        }
        cur += w;
        out.push(c);
    }
    out
}
fn render_cell(content: &str, col_width: usize, padding: usize, align: &str) -> String {
    let truncated = truncate_by_width(content, col_width);
    let tw = display_width(&truncated);
    let fill = if col_width >= tw { col_width - tw } else { 0 };
    let (left_fill, right_fill) = match align {
        "left" => (0, fill),
        "right" => (fill, 0),
        _ => { // center
            let left = fill / 2;
            let right = fill - left;
            (left, right)
        }
    };
    let mut s = String::new();
    s.push_str(&" ".repeat(padding));
    s.push_str(&" ".repeat(left_fill));
    s.push_str(&truncated);
    s.push_str(&" ".repeat(right_fill));
    s.push_str(&" ".repeat(padding));
    s
}
fn build_border_line(indent: &str, left: &str, fill: &str, join: &str, right: &str, interiors: &[usize]) -> String {
    let mut s = String::new();
    s.push_str(indent);
    s.push_str(left);
    for (i, w) in interiors.iter().enumerate() {
        if i > 0 { s.push_str(join); }
        s.push_str(&fill.repeat(*w));
    }
    s.push_str(right);
    s.push('\n');
    s
}

struct CsvRecordRaw {
    fields: Vec<Vec<u8>>,
    byte_offset: usize,
    line: usize,
}

fn parse_csv_raw(data: &[u8], delim: u8) -> Result<Vec<CsvRecordRaw>, (String, bool)> {
    // bool indicates is_parse_error (true for parse error, false for generic CSV error)
    let mut records: Vec<CsvRecordRaw> = Vec::new();
    let mut pos: usize = 0;
    let n = data.len();
    let mut line: usize = 1;
    let mut record_start: usize = 0;
    let mut record_line: usize = 1;
    let mut fields: Vec<Vec<u8>> = Vec::new();
    let mut field: Vec<u8> = Vec::new();
    let mut in_quotes = false;
    let mut need_record_start_update = false;

    // helper to push record when newline encountered or EOF
    // We'll loop
    while pos < n {
        let b = data[pos];
        if in_quotes {
            if b == b'"' {
                if pos + 1 < n && data[pos+1] == b'"' {
                    field.push(b'"');
                    pos += 2;
                    continue;
                } else {
                    in_quotes = false;
                    pos += 1;
                    continue;
                }
            } else {
                // inside quotes, any byte including delimiter and newline is part of field
                // Note: we push raw byte; for newline inside quotes we don't increment line nor start new record
                field.push(b);
                pos += 1;
                continue;
            }
        } else {
            // not in quotes
            if b == b'"' && field.is_empty() {
                // start quoted field
                in_quotes = true;
                pos += 1;
                continue;
            }
            if b == delim {
                fields.push(std::mem::take(&mut field));
                pos += 1;
                continue;
            }
            if b == b'\r' || b == b'\n' {
                // end of record
                // push current field
                fields.push(std::mem::take(&mut field));
                // Determine if this is an empty line to skip: fields == [empty] and record is just newline(s)
                // Check if fields len ==1 && fields[0].is_empty() and record length is just separators?
                // Simpler: if fields.len()==1 && fields[0].is_empty() && pos == record_start || (pos>record_start && data[record_start]==b'\r' && pos==record_start+1) then empty.
                // But we need to know if the line was empty (no fields except empty). That happens when we started at record_start and immediately hit newline without any other content.
                // For a line like "\n", fields will be [empty] (one empty field). We want to skip.
                // For header like "a,b\n", fields will be ["a","b"] not empty.
                let is_empty_line = fields.len() == 1 && fields[0].is_empty() && {
                    // check that the raw slice from record_start to pos is just "\r" or "\n" or "\r\n"
                    let slice = &data[record_start..pos];
                    // Note: pos is at newline char, slice excludes newline? Actually record_start points to start, pos at newline char, slice does not include newline.
                    // For empty line, slice should be empty (zero bytes) because we started at newline. But we pushed field before checking, so slice is empty.
                    slice.is_empty()
                };
                // Need to handle \r\n: pos at b'\r', next is \n. That case slice still empty, but we will handle \r\n as single newline later.
                // For now, pos is at newline char, we will after pushing, decide.
                let is_empty = is_empty_line;
                if !is_empty {
                    records.push(CsvRecordRaw { fields: std::mem::take(&mut fields), byte_offset: record_start, line: record_line });
                } else {
                    // reset fields for next record (already taken? we took fields, but we need to clear)
                    fields = Vec::new();
                }
                // For \r\n, consume both chars as one line break
                if b == b'\r' && pos + 1 < n && data[pos+1] == b'\n' {
                    pos += 2;
                } else {
                    pos += 1;
                }
                line += 1;
                record_start = pos;
                record_line = line;
                // reset field already empty
                continue;
            }
            // regular byte
            field.push(b);
            pos += 1;
            continue;
        }
    }
    // EOF handling
    // If in_quotes at EOF, we could treat as error? But for now just close.
    // If we have pending field/fields, create last record
    // This happens if file does not end with newline
    // Need to handle: if we were in middle of record, field has content or fields has some.
    if in_quotes {
        // Unterminated quote - treat as parse error? But we will just close.
        // Push whatever.
    }
    // If there is pending data: fields not empty or field not empty or record_start < n
    // Check if we have any pending: if fields.is_empty() && field.is_empty() && record_start == n => no pending (empty file)
    // Else push.
    if !fields.is_empty() || !field.is_empty() || record_start < n {
        fields.push(std::mem::take(&mut field));
        // Check empty line again (for file ending with empty? but EOF not newline, no empty)
        let is_empty_line = fields.len() == 1 && fields[0].is_empty() && record_start == n; // not needed
        // Actually if file ends without newline and fields is [""] (empty), that would be one empty field record like file "\n"? But at EOF with no newline, fields [""] corresponds to empty line? But such file with zero bytes we already handled no pending.
        // For usual case, include.
        // For empty line at EOF without newline, like file with "a,b\n" already handled, no pending.
        // So we need to see if fields == [empty] and original slice from record_start to n is empty => empty line but not counted? But EOF with empty slice not possible because record_start==n means no data.
        let slice_is_empty = record_start == n;
        let is_empty = fields.len() == 1 && fields[0].is_empty() && slice_is_empty;
        if !is_empty {
            // But also need to consider case where fields is [empty] due to trailing delimiter? e.g., "a,b," => fields ["a","b",""] => not empty.
            records.push(CsvRecordRaw { fields, byte_offset: record_start, line: record_line });
        }
    }
    // Validate flexible: check field counts consistency
    if !records.is_empty() {
        let first_len = records[0].fields.len();
        for (idx, rec) in records.iter().enumerate().skip(1) {
            if rec.fields.len() != first_len {
                let msg = format!("CSV error: record {} (line: {}, byte: {}): found record with {} fields, but the previous record has {} fields", idx, rec.line, rec.byte_offset, rec.fields.len(), first_len);
                return Err((msg, false));
            }
        }
    }
    Ok(records)
}

fn main() {
    let cmd = Command::new("csview")
        .version("1.3.4")
        .about("A high performance csv viewer with cjk/emoji support.")
        .arg(Arg::new("FILE").value_name("FILE").help("File to view"))
        .arg(Arg::new("no-headers").short('H').long("no-headers").help("Specify that the input has no header row").action(clap::ArgAction::SetTrue))
        .arg(Arg::new("number").short('n').long("number").help("Prepend a column of line numbers to the table").action(clap::ArgAction::SetTrue))
        .arg(Arg::new("tsv").short('t').long("tsv").help("Use '\\t' as delimiter for tsv").action(clap::ArgAction::SetTrue).conflicts_with("delimiter"))
        .arg(Arg::new("delimiter").short('d').long("delimiter").value_name("DELIMITER").default_value(",").help("Specify the field delimiter").value_parser(value_parser!(char)))
        .arg(Arg::new("style").short('s').long("style").value_name("STYLE").default_value("sharp").value_parser(["none","ascii","ascii2","sharp","rounded","reinforced","markdown","grid"]).help("Specify the border style"))
        .arg(Arg::new("padding").short('p').long("padding").value_name("PADDING").default_value("1").value_parser(value_parser!(usize)).help("Specify padding for table cell"))
        .arg(Arg::new("indent").short('i').long("indent").value_name("INDENT").default_value("0").value_parser(value_parser!(usize)).help("Specify global indent for table"))
        .arg(Arg::new("sniff").long("sniff").value_name("LIMIT").default_value("1000").value_parser(value_parser!(usize)).help("Limit column widths sniffing to the specified number of rows. Specify \"0\" to cancel limit"))
        .arg(Arg::new("header-align").long("header-align").value_name("HEADER_ALIGN").default_value("center").value_parser(["left","center","right"]).help("Specify the alignment of the table header"))
        .arg(Arg::new("body-align").long("body-align").value_name("BODY_ALIGN").default_value("left").value_parser(["left","center","right"]).help("Specify the alignment of the table body"))
        .arg(Arg::new("disable-pager").short('P').long("disable-pager").help("Disable pager").action(clap::ArgAction::SetTrue));

    let matches = match cmd.try_get_matches() {
        Ok(m) => m,
        Err(e) => e.exit(),
    };

    let file_opt = matches.get_one::<String>("FILE").cloned();
    let no_headers = matches.get_flag("no-headers");
    let number = matches.get_flag("number");
    let tsv = matches.get_flag("tsv");
    let delimiter_char = *matches.get_one::<char>("delimiter").unwrap();
    let style_str = matches.get_one::<String>("style").unwrap().clone();
    let padding = *matches.get_one::<usize>("padding").unwrap();
    let indent = *matches.get_one::<usize>("indent").unwrap();
    let sniff = *matches.get_one::<usize>("sniff").unwrap();
    let header_align = matches.get_one::<String>("header-align").unwrap().clone();
    let body_align = matches.get_one::<String>("body-align").unwrap().clone();
    let disable_pager = matches.get_flag("disable-pager");

    let delim: u8 = if tsv { b'\t' } else { delimiter_char as u8 };

    // Read data
    let data: Vec<u8> = if let Some(path) = file_opt.as_ref() {
        match std::fs::read(path) {
            Ok(b) => b,
            Err(e) => {
                eprintln!("csview: {}", e);
                std::process::exit(1);
            }
        }
    } else {
        let mut buf = Vec::new();
        use std::io::Read;
        std::io::stdin().lock().read_to_end(&mut buf).unwrap();
        buf
    };

    let data_slice: &[u8] = if data.starts_with(&[0xEF, 0xBB, 0xBF]) {
        &data[3..]
    } else {
        &data[..]
    };

    let raw_records = match parse_csv_raw(data_slice, delim) {
        Ok(r) => r,
        Err((msg, is_parse)) => {
            if is_parse {
                eprintln!("csview: {}", msg);
            } else {
                eprintln!("csview: {}", msg);
            }
            std::process::exit(1);
        }
    };

    // Convert raw fields from Vec<u8> to String, handling invalid utf-8
    let mut records: Vec<Vec<String>> = Vec::new();
    for (rec_idx, raw) in raw_records.iter().enumerate() {
        let mut fields_str: Vec<String> = Vec::new();
        for (field_idx, field_bytes) in raw.fields.iter().enumerate() {
            match String::from_utf8(field_bytes.clone()) {
                Ok(s) => fields_str.push(s),
                Err(_) => {
                    // Find near byte index? Use first invalid byte index
                    let err_msg = format!("CSV parse error: record {} (line {}, field: {}, byte: {}): invalid utf-8: invalid UTF-8 in field {} near byte index {}", rec_idx, raw.line, field_idx, raw.byte_offset, field_idx, 0);
                    eprintln!("csview: {}", err_msg);
                    std::process::exit(1);
                }
            }
        }
        records.push(fields_str);
    }

    // Split header/body
    let (header_opt, body): (Option<Vec<String>>, Vec<Vec<String>>) = if no_headers {
        (None, records)
    } else {
        if records.is_empty() {
            (None, Vec::new())
        } else {
            let mut rec = records;
            let h = rec.remove(0);
            (Some(h), rec)
        }
    };

    let ncols_original = if let Some(h) = header_opt.as_ref() {
        h.len()
    } else if !body.is_empty() {
        body[0].len()
    } else {
        0
    };

    // Compute column widths
    let mut col_widths = vec![0usize; ncols_original];
    if let Some(h) = header_opt.as_ref() {
        for (i, c) in h.iter().enumerate() {
            let w = display_width(c);
            if w > col_widths[i] { col_widths[i] = w; }
        }
    }
    let sniff_limit = if sniff == 0 { body.len() } else { std::cmp::min(sniff, body.len()) };
    for row in body.iter().take(sniff_limit) {
        for (i, c) in row.iter().enumerate() {
            if i < col_widths.len() {
                let w = display_width(c);
                if w > col_widths[i] { col_widths[i] = w; }
            }
        }
    }

    // Number column handling
    let has_number = number;
    let logical_has_header = !no_headers;
    let include_number = if has_number {
        if logical_has_header { true } else { !body.is_empty() }
    } else { false };

    let number_width = if include_number {
        if header_opt.is_some() || (records.is_empty() && !no_headers) || (header_opt.is_none() && logical_has_header && records.is_empty()) {
            // header "#" case
            let mut w = display_width("#");
            for idx in 1..=body.len() {
                let s = idx.to_string();
                let wc = display_width(&s);
                if wc > w { w = wc; }
            }
            w
        } else {
            // no header
            let mut w = 0usize;
            for idx in 1..=body.len() {
                let s = idx.to_string();
                let wc = display_width(&s);
                if wc > w { w = wc; }
            }
            w
        }
    } else { 0 };

    let mut combined_widths: Vec<usize> = Vec::new();
    let mut combined_interiors: Vec<usize> = Vec::new();
    if include_number {
        combined_widths.push(number_width);
        combined_interiors.push(number_width + 2*padding);
    }
    for &w in &col_widths {
        combined_widths.push(w);
        combined_interiors.push(w + 2*padding);
    }
    let ncols_total = combined_widths.len();
    let indent_str = " ".repeat(indent);

    // Prepare header cells
    let mut header_cells_rendered: Option<Vec<String>> = header_opt.as_ref().map(|h| {
        let mut cells = Vec::new();
        if include_number {
            cells.push(render_cell("#", number_width, padding, &header_align));
        }
        for (i, c) in h.iter().enumerate() {
            cells.push(render_cell(c, col_widths[i], padding, &header_align));
        }
        cells
    });

    if header_cells_rendered.is_none() && include_number && records.is_empty() && !no_headers {
        // empty file with number and header logical
        let mut cells = Vec::new();
        cells.push(render_cell("#", number_width, padding, &header_align));
        header_cells_rendered = Some(cells);
    }

    let has_header = header_cells_rendered.is_some();
    let has_body = !body.is_empty();

    let mut body_rows_rendered: Vec<Vec<String>> = Vec::new();
    for (idx, row) in body.iter().enumerate() {
        let mut cells = Vec::new();
        if include_number {
            let num = (idx+1).to_string();
            cells.push(render_cell(&num, number_width, padding, &body_align));
        }
        for (i, c) in row.iter().enumerate() {
            cells.push(render_cell(c, col_widths[i], padding, &body_align));
        }
        body_rows_rendered.push(cells);
    }

    // Special case: if include_number && !has_header && !has_body but we already handled empty header? Then header_cells_rendered already set.

    let output: String = match style_str.as_str() {
        "none" => {
            let mut out = String::new();
            if let Some(cells) = header_cells_rendered.as_ref() {
                let line = indent_str.clone() + &cells.concat();
                out.push_str(&line);
                out.push('\n');
            }
            for cells in &body_rows_rendered {
                let line = indent_str.clone() + &cells.concat();
                out.push_str(&line);
                out.push('\n');
            }
            if out.is_empty() {
                out.push_str(&indent_str);
                out.push('\n');
            }
            out
        },
        "ascii2" => {
            let mut out = String::new();
            if let Some(cells) = header_cells_rendered.as_ref() {
                if cells.is_empty() {
                    out.push_str(&format!("{}  \n", indent_str));
                } else {
                    let row_inner = cells.join("|");
                    out.push_str(&indent_str);
                    out.push(' ');
                    out.push_str(&row_inner);
                    out.push(' ');
                    out.push('\n');
                }
            }
            if has_header && has_body {
                let sep_inner = combined_interiors.iter().map(|w| "-".repeat(*w)).collect::<Vec<_>>().join("+");
                out.push_str(&indent_str);
                out.push(' ');
                out.push_str(&sep_inner);
                out.push(' ');
                out.push('\n');
            }
            for cells in &body_rows_rendered {
                if cells.is_empty() {
                    out.push_str(&format!("{}  \n", indent_str));
                } else {
                    let row_inner = cells.join("|");
                    out.push_str(&indent_str);
                    out.push(' ');
                    out.push_str(&row_inner);
                    out.push(' ');
                    out.push('\n');
                }
            }
            if out.is_empty() {
                out.push_str(&format!("{}  \n", indent_str));
            }
            out
        },
        "markdown" => {
            let mut out = String::new();
            if let Some(cells) = header_cells_rendered.as_ref() {
                if cells.is_empty() {
                    out.push_str(&format!("{}||\n", indent_str));
                } else {
                    let row_inner = cells.join("|");
                    out.push_str(&indent_str);
                    out.push('|');
                    out.push_str(&row_inner);
                    out.push('|');
                    out.push('\n');
                }
            }
            if has_header && has_body {
                let sep_inner = combined_interiors.iter().map(|w| "-".repeat(*w)).collect::<Vec<_>>().join("|");
                out.push_str(&indent_str);
                out.push('|');
                out.push_str(&sep_inner);
                out.push('|');
                out.push('\n');
            }
            for cells in &body_rows_rendered {
                if cells.is_empty() {
                    out.push_str(&format!("{}||\n", indent_str));
                } else {
                    let row_inner = cells.join("|");
                    out.push_str(&indent_str);
                    out.push('|');
                    out.push_str(&row_inner);
                    out.push('|');
                    out.push('\n');
                }
            }
            if out.is_empty() {
                out.push_str(&format!("{}||\n", indent_str));
            }
            out
        },
        _ => {
            // bordered styles
            let (top_left, top_fill, top_join, top_right, mid_left, mid_fill, mid_join, mid_right, row_left, row_mid, row_right, bottom_left, bottom_fill, bottom_join, bottom_right) = match style_str.as_str() {
                "sharp" => ("┌","─","┬","┐","├","─","┼","┤","│","│","│","└","─","┴","┘"),
                "rounded" => ("╭","─","┬","╮","├","─","┼","┤","│","│","│","╰","─","┴","╯"),
                "reinforced" => ("┏","─","┬","┓","├","─","┼","┤","│","│","│","┗","─","┴","┛"),
                "ascii" => ("+","-","+","+","+","-","+","+","|","|","|","+","-","+","+"),
                "grid" => ("┌","─","┬","┐","├","─","┼","┤","│","│","│","└","─","┴","┘"),
                _ => ("┌","─","┬","┐","├","─","┼","┤","│","│","│","└","─","┴","┘"),
            };
            let mut out = String::new();
            if ncols_total == 0 {
                out.push_str(&build_border_line(&indent_str, top_left, top_fill, top_join, top_right, &combined_interiors));
                if has_header {
                    out.push_str(&format!("{}{}{}\n", indent_str, row_left, row_right));
                } else if has_body {
                    for _ in &body_rows_rendered {
                        out.push_str(&format!("{}{}{}\n", indent_str, row_left, row_right));
                    }
                } else {
                    out.push_str(&format!("{}{}{}\n", indent_str, row_left, row_right));
                }
                out.push_str(&build_border_line(&indent_str, bottom_left, bottom_fill, bottom_join, bottom_right, &combined_interiors));
                out
            } else {
                out.push_str(&build_border_line(&indent_str, top_left, top_fill, top_join, top_right, &combined_interiors));
                if let Some(cells) = header_cells_rendered.as_ref() {
                    let row_inner = cells.join(row_mid);
                    out.push_str(&indent_str);
                    out.push_str(row_left);
                    out.push_str(&row_inner);
                    out.push_str(row_right);
                    out.push('\n');
                }
                if has_header && has_body {
                    out.push_str(&build_border_line(&indent_str, mid_left, mid_fill, mid_join, mid_right, &combined_interiors));
                }
                for (idx, cells) in body_rows_rendered.iter().enumerate() {
                    let row_inner = cells.join(row_mid);
                    out.push_str(&indent_str);
                    out.push_str(row_left);
                    out.push_str(&row_inner);
                    out.push_str(row_right);
                    out.push('\n');
                    if style_str == "grid" && idx + 1 < body_rows_rendered.len() {
                        out.push_str(&build_border_line(&indent_str, mid_left, mid_fill, mid_join, mid_right, &combined_interiors));
                    }
                }
                out.push_str(&build_border_line(&indent_str, bottom_left, bottom_fill, bottom_join, bottom_right, &combined_interiors));
                out
            }
        }
    };

    if disable_pager {
        print!("{}", output);
    } else {
        // pager handling: if stdout is tty, pipe to pager, else direct
        let is_tty = unsafe { libc_isatty() };
        if is_tty {
            // Try pager
            let pager = std::env::var("PAGER").unwrap_or_else(|_| "less".to_string());
            // Simple attempt
            use std::process::{Command, Stdio};
            use std::io::Write;
            let mut cmd = Command::new(&pager);
            if pager.contains("less") {
                cmd.arg("-R").arg("-F").arg("-X");
            }
            cmd.stdin(Stdio::piped());
            if let Ok(mut child) = cmd.spawn() {
                if let Some(mut stdin) = child.stdin.take() {
                    let _ = stdin.write_all(output.as_bytes());
                }
                let _ = child.wait();
                return;
            } else {
                print!("{}", output);
            }
        } else {
            print!("{}", output);
        }
    }
}

#[inline]
unsafe fn libc_isatty() -> bool {
    extern "C" {
        fn isatty(fd: i32) -> i32;
    }
    isatty(1) != 0
}
