const VERSION_TEXT: &str = "csview 1.3.4\n";

fn print_help_and_exit() -> ! {
    print!("{}", HELP_TEXT);
    std::process::exit(0);
}
fn print_version_and_exit() -> ! {
    print!("{}", VERSION_TEXT);
    std::process::exit(0);
}
fn exit_with_error(msg: &str) -> ! {
    eprint!("{}", msg);
    std::process::exit(2);
}
fn error_invalid_value(arg: &str, val: &str, possible: Option<&str>, msg: &str) -> String {
    if let Some(poss) = possible {
        format!("error: invalid value '{}' for '--{} <{}>'\n  [possible values: {}]\n\nFor more information, try '--help'.\n", val, arg, arg.to_uppercase(), poss)
    } else {
        format!("error: invalid value '{}' for '--{} <{}>': {}\n\nFor more information, try '--help'.\n", val, arg, arg.to_uppercase(), msg)
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    // Manual parsing to match clap
    let mut file: Option<String> = None;
    let mut no_headers = false;
    let mut number = false;
    let mut tsv = false;
    let mut delimiter: char = ',';
    let mut delimiter_set = false;
    let mut style = "sharp".to_string();
    let mut padding: usize = 1;
    let mut indent: usize = 0;
    let mut sniff: usize = 1000;
    let mut header_align = "center".to_string();
    let mut body_align = "left".to_string();
    let mut disable_pager = false;

    let mut i = 1;
    let mut positional_done = false;
    while i < args.len() {
        let arg = &args[i];
        if positional_done {
            if file.is_none() {
                file = Some(arg.clone());
            } else {
                // extra positional? clap would error? For csview, only one FILE argument, extra would be unexpected
                let msg = format!("error: unexpected argument '{}' found\n\nUsage: executable [OPTIONS] [FILE]\n\nFor more information, try '--help'.\n", arg);
                exit_with_error(&msg);
            }
            i+=1;
            continue;
        }
        if arg == "--" {
            positional_done = true;
            i+=1;
            continue;
        }
        if arg == "-h" || arg == "--help" {
            print_help_and_exit();
        }
        if arg == "-V" || arg == "--version" {
            print_version_and_exit();
        }
        // Flags without values
        if arg == "-H" || arg == "--no-headers" {
            no_headers = true;
            i+=1;
            continue;
        }
        if arg == "-n" || arg == "--number" {
            number = true;
            i+=1;
            continue;
        }
        if arg == "-t" || arg == "--tsv" {
            tsv = true;
            i+=1;
            continue;
        }
        if arg == "-P" || arg == "--disable-pager" {
            disable_pager = true;
            i+=1;
            continue;
        }
        // Options with values
        // Helper to get next value
        let mut consumed_next = false;
        let mut opt_name: Option<&str> = None;
        let mut opt_val: Option<String> = None;

        // Long options with =
        if arg.starts_with("--") && arg.contains('=') {
            let parts: Vec<&str> = arg.splitn(2, '=').collect();
            let name = parts[0];
            let val = parts[1];
            // Map name to option
            match name {
                "--delimiter" => { opt_name = Some("delimiter"); opt_val = Some(val.to_string()); },
                "--style" => { opt_name = Some("style"); opt_val = Some(val.to_string()); },
                "--padding" => { opt_name = Some("padding"); opt_val = Some(val.to_string()); },
                "--indent" => { opt_name = Some("indent"); opt_val = Some(val.to_string()); },
                "--sniff" => { opt_name = Some("sniff"); opt_val = Some(val.to_string()); },
                "--header-align" => { opt_name = Some("header-align"); opt_val = Some(val.to_string()); },
                "--body-align" => { opt_name = Some("body-align"); opt_val = Some(val.to_string()); },
                _ => {
                    // unknown long
                    let msg = format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: executable [OPTIONS] [FILE]\n\nFor more information, try '--help'.\n", name, name, name);
                    exit_with_error(&msg);
                }
            }
        } else if arg.starts_with("--") {
            match arg.as_str() {
                "--delimiter" => { opt_name = Some("delimiter"); consumed_next = true; },
                "--style" => { opt_name = Some("style"); consumed_next = true; },
                "--padding" => { opt_name = Some("padding"); consumed_next = true; },
                "--indent" => { opt_name = Some("indent"); consumed_next = true; },
                "--sniff" => { opt_name = Some("sniff"); consumed_next = true; },
                "--header-align" => { opt_name = Some("header-align"); consumed_next = true; },
                "--body-align" => { opt_name = Some("body-align"); consumed_next = true; },
                _ => {
                    // unknown
                    let msg = format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: executable [OPTIONS] [FILE]\n\nFor more information, try '--help'.\n", arg, arg, arg);
                    exit_with_error(&msg);
                }
            }
            if consumed_next {
                if i+1 >= args.len() {
                    // missing value? clap would error with "a value is required"
                    // But we need to reproduce clap's message for required value missing
                    // For now generic
                    let arg_name = &arg[2..];
                    let msg = format!("error: a value is required for '--{} <{}>' but none was supplied\n  [possible values: ...]\n\nFor more information, try '--help'.\n", arg_name, arg_name.to_uppercase());
                    // However we can just exit with that
                    exit_with_error(&msg);
                }
                opt_val = Some(args[i+1].clone());
            }
        } else if arg.starts_with("-") && arg.len() > 1 {
            // short options, may be combined? csview short options are -H -n -t -d -s -p -i -P -h -V
            // For simplicity, handle each arg as single short with optional value attached or next.
            // If arg like "-s" alone
            // If arg like "-s=sharp" not typical
            // If arg like "-d," with value attached? e.g., "-d,"? But delimiter is char, could be "-d,"? Our delimiter handling expects separate.
            // We'll parse char by char for flags, but values need handling.
            // Simplify: if arg length ==2, single short
            // else if arg starts with -d etc with value attached like "-d," or "-sascii"
            // Let's handle generic:
            if arg.len() == 2 {
                let ch = arg.chars().nth(1).unwrap();
                match ch {
                    'H' => { no_headers = true; i+=1; continue; },
                    'n' => { number = true; i+=1; continue; },
                    't' => { tsv = true; i+=1; continue; },
                    'P' => { disable_pager = true; i+=1; continue; },
                    'd' => { opt_name = Some("delimiter"); consumed_next = true; },
                    's' => { opt_name = Some("style"); consumed_next = true; },
                    'p' => { opt_name = Some("padding"); consumed_next = true; },
