                        exit_with_error(&msg);
                    }
                    opt_val = Some(args[i+1].clone());
                }
            } else {
                // Combined or attached value: e.g., "-d," or "-sgrid" or "-pd" ? Rare
                // We'll parse first char, if it's an option taking value, the rest is value
                let chars: Vec<char> = arg[1..].chars().collect();
                let first = chars[0];
                let rest: String = chars[1..].iter().collect();
                match first {
                    'H' | 'n' | 't' | 'P' => {
                        // combined flags like "-nH"? Not expected, but handle
                        // If first char is flag without value, and rest contains more flags
                        // We'll iterate each char
                        let mut idx = 0;
