                                'd' | 's' | 'p' | 'i' => {
                                    // option with value: remaining chars is value, or next arg
                                    let remaining: String = chars[idx+1..].iter().collect();
                                    if !remaining.is_empty() {
                                        opt_name = Some(match c { 'd' => "delimiter", 's' => "style", 'p' => "padding", 'i' => "indent", _=> unreachable!() });
                                        opt_val = Some(remaining);
                                        handled = true;
                                        break;
                                    } else {
                                        opt_name = Some(match c { 'd' => "delimiter", 's' => "style", 'p' => "padding", 'i' => "indent", _=> unreachable!() });
                                        consumed_next = true;
                                        if i+1 >= args.len() {
                                            let msg = format!("error: a value is required for '-{} <{}>' but none was supplied\n\nFor more information, try '--help'.\n", c, c.to_uppercase());
                                            exit_with_error(&msg);
                                        }
                                        opt_val = Some(args[i+1].clone());
                                        handled = true;
                                        break;
                                    }
                                },
                                'h' => { print_help_and_exit(); },
