                "body-align" => {
                    let valid = ["left","center","right"];
                    if !valid.contains(&val.as_str()) {
                        let msg = format!("error: invalid value '{}' for '--body-align <BODY_ALIGN>'\n  [possible values: left, center, right]\n\nFor more information, try '--help'.\n", val);
                        exit_with_error(&msg);
                    }
                    body_align = val;
                },
                _ => {}
            }
            if consumed_next {
                i+=2;
            } else {
                // for --opt=val or -sval already consumed only one arg
                if arg.contains('=') || (arg.starts_with("-") && arg.len()>2) {
                    i+=1;
                } else {
                    // shouldn't happen
                    i+=1;
                }
            }
            continue;
        }

        // unknown? Should not reach
        i+=1;
    }

    // Check tsv conflict if delimiter set after tsv?
    if tsv && delimiter_set {
        let msg = format!("error: the argument '--tsv' cannot be used with '--delimiter <DELIMITER>'\n\nUsage: executable --disable-pager --tsv <FILE>\n\nFor more information, try '--help'.\n");
        exit_with_error(&msg);
    }

    // Also need to handle unknown args like --unknown already handled

