use std::path::PathBuf;

fn display_width(s: &str) -> usize {
    use unicode_width::UnicodeWidthChar;
    s.chars().map(|c| c.width().unwrap_or(0)).sum()
}
fn truncate_by_width(s: &str, max_width: usize) -> String {
    use unicode_width::UnicodeWidthChar;
    let mut cur = 0usize;
    let mut out = String::new();
    for c in s.chars() {
        let w = c.width().unwrap_or(0);
        if cur + w > max_width {
            break;
        }
        cur += w;
        out.push(c);
    }
    out
}
fn render_cell(content: &str, col_width: usize, padding: usize, align: &str) -> String {
    let truncated = truncate_by_width(content, col_width);
    let tw = display_width(&truncated);
    let fill = if col_width >= tw { col_width - tw } else { 0 };
    let (left_fill, right_fill) = match align {
        "left" => (0, fill),
        "right" => (fill, 0),
        _ => {
            let left = fill / 2;
            let right = fill - left;
            (left, right)
        }
    };
    let mut s = String::new();
    s.push_str(&" ".repeat(padding));
    s.push_str(&" ".repeat(left_fill));
    s.push_str(&truncated);
    s.push_str(&" ".repeat(right_fill));
    s.push_str(&" ".repeat(padding));
    s
}
fn build_border_line(indent: &str, left: &str, fill: &str, join: &str, right: &str, interiors: &[usize]) -> String {
    let mut s = String::new();
    s.push_str(indent);
    s.push_str(left);
    for (i, w) in interiors.iter().enumerate() {
        if i > 0 { s.push_str(join); }
        s.push_str(&fill.repeat(*w));
    }
    s.push_str(right);
    s.push('\n');
    s
}

const HELP_TEXT: &str = r#"A high performance csv viewer with cjk/emoji support.

Usage: executable [OPTIONS] [FILE]

Arguments:
  [FILE]
          File to view

Options:
  -H, --no-headers
          Specify that the input has no header row
  -n, --number
          Prepend a column of line numbers to the table
  -t, --tsv
          Use '\t' as delimiter for tsv
  -d, --delimiter <DELIMITER>
          Specify the field delimiter [default: ,]
  -s, --style <STYLE>
          Specify the border style [default: sharp] [possible values: none, ascii, ascii2, sharp,
          rounded, reinforced, markdown, grid]
  -p, --padding <PADDING>
          Specify padding for table cell [default: 1]
  -i, --indent <INDENT>
          Specify global indent for table [default: 0]
      --sniff <LIMIT>
          Limit column widths sniffing to the specified number of rows. Specify "0" to cancel limit
          [default: 1000]
      --header-align <HEADER_ALIGN>
          Specify the alignment of the table header [default: center] [possible values: left,
          center, right]
      --body-align <BODY_ALIGN>
          Specify the alignment of the table body [default: left] [possible values: left, center,
          right]
  -P, --disable-pager
          Disable pager
  -h, --help
          Print help
  -V, --version
          Print version
"#;

const VERSION_TEXT: &str = "csview 1.3.4\n";

fn print_help_and_exit() -> ! {
    print!("{}", HELP_TEXT);
    std::process::exit(0);
}
fn print_version_and_exit() -> ! {
    print!("{}", VERSION_TEXT);
    std::process::exit(0);
}
fn exit_with_error(msg: &str) -> ! {
    eprint!("{}", msg);
    std::process::exit(2);
}
fn error_invalid_value(arg: &str, val: &str, possible: Option<&str>, msg: &str) -> String {
    if let Some(poss) = possible {
        format!("error: invalid value '{}' for '--{} <{}>'\n  [possible values: {}]\n\nFor more information, try '--help'.\n", val, arg, arg.to_uppercase(), poss)
    } else {
        format!("error: invalid value '{}' for '--{} <{}>': {}\n\nFor more information, try '--help'.\n", val, arg, arg.to_uppercase(), msg)
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    // Manual parsing to match clap
    let mut file: Option<String> = None;
    let mut no_headers = false;
    let mut number = false;
    let mut tsv = false;
    let mut delimiter: char = ',';
    let mut delimiter_set = false;
    let mut style = "sharp".to_string();
    let mut padding: usize = 1;
    let mut indent: usize = 0;
    let mut sniff: usize = 1000;
    let mut header_align = "center".to_string();
    let mut body_align = "left".to_string();
    let mut disable_pager = false;

    let mut i = 1;
    let mut positional_done = false;
    while i < args.len() {
        let arg = &args[i];
        if positional_done {
            if file.is_none() {
                file = Some(arg.clone());
            } else {
                // extra positional? clap would error? For csview, only one FILE argument, extra would be unexpected
                let msg = format!("error: unexpected argument '{}' found\n\nUsage: executable [OPTIONS] [FILE]\n\nFor more information, try '--help'.\n", arg);
                exit_with_error(&msg);
            }
            i+=1;
            continue;
        }
        if arg == "--" {
            positional_done = true;
            i+=1;
            continue;
        }
        if arg == "-h" || arg == "--help" {
            print_help_and_exit();
        }
        if arg == "-V" || arg == "--version" {
            print_version_and_exit();
        }
        // Flags without values
        if arg == "-H" || arg == "--no-headers" {
            no_headers = true;
            i+=1;
            continue;
        }
        if arg == "-n" || arg == "--number" {
            number = true;
            i+=1;
            continue;
        }
        if arg == "-t" || arg == "--tsv" {
            tsv = true;
            i+=1;
            continue;
        }
        if arg == "-P" || arg == "--disable-pager" {
            disable_pager = true;
            i+=1;
            continue;
        }
        // Options with values
        // Helper to get next value
        let mut consumed_next = false;
        let mut opt_name: Option<&str> = None;
        let mut opt_val: Option<String> = None;

        // Long options with =
        if arg.starts_with("--") && arg.contains('=') {
            let parts: Vec<&str> = arg.splitn(2, '=').collect();
            let name = parts[0];
            let val = parts[1];
            // Map name to option
            match name {
                "--delimiter" => { opt_name = Some("delimiter"); opt_val = Some(val.to_string()); },
                "--style" => { opt_name = Some("style"); opt_val = Some(val.to_string()); },
                "--padding" => { opt_name = Some("padding"); opt_val = Some(val.to_string()); },
                "--indent" => { opt_name = Some("indent"); opt_val = Some(val.to_string()); },
                "--sniff" => { opt_name = Some("sniff"); opt_val = Some(val.to_string()); },
                "--header-align" => { opt_name = Some("header-align"); opt_val = Some(val.to_string()); },
                "--body-align" => { opt_name = Some("body-align"); opt_val = Some(val.to_string()); },
                _ => {
                    // unknown long
                    let msg = format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: executable [OPTIONS] [FILE]\n\nFor more information, try '--help'.\n", name, name, name);
                    exit_with_error(&msg);
                }
            }
        } else if arg.starts_with("--") {
            match arg.as_str() {
                "--delimiter" => { opt_name = Some("delimiter"); consumed_next = true; },
                "--style" => { opt_name = Some("style"); consumed_next = true; },
                "--padding" => { opt_name = Some("padding"); consumed_next = true; },
                "--indent" => { opt_name = Some("indent"); consumed_next = true; },
                "--sniff" => { opt_name = Some("sniff"); consumed_next = true; },
                "--header-align" => { opt_name = Some("header-align"); consumed_next = true; },
                "--body-align" => { opt_name = Some("body-align"); consumed_next = true; },
                _ => {
                    // unknown
                    let msg = format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: executable [OPTIONS] [FILE]\n\nFor more information, try '--help'.\n", arg, arg, arg);
                    exit_with_error(&msg);
                }
            }
            if consumed_next {
                if i+1 >= args.len() {
                    // missing value? clap would error with "a value is required"
                    // But we need to reproduce clap's message for required value missing
                    // For now generic
                    let arg_name = &arg[2..];
                    let msg = format!("error: a value is required for '--{} <{}>' but none was supplied\n  [possible values: ...]\n\nFor more information, try '--help'.\n", arg_name, arg_name.to_uppercase());
                    // However we can just exit with that
                    exit_with_error(&msg);
                }
                opt_val = Some(args[i+1].clone());
            }
        } else if arg.starts_with("-") && arg.len() > 1 {
            // short options, may be combined? csview short options are -H -n -t -d -s -p -i -P -h -V
            // For simplicity, handle each arg as single short with optional value attached or next.
            // If arg like "-s" alone
            // If arg like "-s=sharp" not typical
            // If arg like "-d," with value attached? e.g., "-d,"? But delimiter is char, could be "-d,"? Our delimiter handling expects separate.
            // We'll parse char by char for flags, but values need handling.
            // Simplify: if arg length ==2, single short
            // else if arg starts with -d etc with value attached like "-d," or "-sascii"
            // Let's handle generic:
            if arg.len() == 2 {
                let ch = arg.chars().nth(1).unwrap();
                match ch {
                    'H' => { no_headers = true; i+=1; continue; },
                    'n' => { number = true; i+=1; continue; },
                    't' => { tsv = true; i+=1; continue; },
                    'P' => { disable_pager = true; i+=1; continue; },
                    'd' => { opt_name = Some("delimiter"); consumed_next = true; },
                    's' => { opt_name = Some("style"); consumed_next = true; },
                    'p' => { opt_name = Some("padding"); consumed_next = true; },
                    'i' => { opt_name = Some("indent"); consumed_next = true; },
                    'h' => { print_help_and_exit(); },
                    'V' => { print_version_and_exit(); },
                    _ => {
                        let msg = format!("error: unexpected argument '-{}' found\n\n  tip: to pass '-{}' as a value, use '-- -{}'\n\nUsage: executable [OPTIONS] [FILE]\n\nFor more information, try '--help'.\n", ch, ch, ch);
                        exit_with_error(&msg);
                    }
                }
                if consumed_next {
                    if i+1 >= args.len() {
                        let msg = format!("error: a value is required for '-{} <{}>' but none was supplied\n\nFor more information, try '--help'.\n", ch, ch.to_uppercase());
                        exit_with_error(&msg);
                    }
                    opt_val = Some(args[i+1].clone());
                }
            } else {
                // Combined or attached value: e.g., "-d," or "-sgrid" or "-pd" ? Rare
                // We'll parse first char, if it's an option taking value, the rest is value
                let chars: Vec<char> = arg[1..].chars().collect();
                let first = chars[0];
                let rest: String = chars[1..].iter().collect();
                match first {
                    'H' | 'n' | 't' | 'P' => {
                        // combined flags like "-nH"? Not expected, but handle
                        // If first char is flag without value, and rest contains more flags
                        // We'll iterate each char
                        let mut idx = 0;
                        let mut handled = false;
                        while idx < chars.len() {
                            let c = chars[idx];
                            match c {
                                'H' => { no_headers = true; idx+=1; },
                                'n' => { number = true; idx+=1; },
                                't' => { tsv = true; idx+=1; },
                                'P' => { disable_pager = true; idx+=1; },
                                'd' | 's' | 'p' | 'i' => {
                                    // option with value: remaining chars is value, or next arg
                                    let remaining: String = chars[idx+1..].iter().collect();
                                    if !remaining.is_empty() {
                                        opt_name = Some(match c { 'd' => "delimiter", 's' => "style", 'p' => "padding", 'i' => "indent", _=> unreachable!() });
                                        opt_val = Some(remaining);
                                        handled = true;
                                        break;
                                    } else {
                                        opt_name = Some(match c { 'd' => "delimiter", 's' => "style", 'p' => "padding", 'i' => "indent", _=> unreachable!() });
                                        consumed_next = true;
                                        if i+1 >= args.len() {
                                            let msg = format!("error: a value is required for '-{} <{}>' but none was supplied\n\nFor more information, try '--help'.\n", c, c.to_uppercase());
                                            exit_with_error(&msg);
                                        }
                                        opt_val = Some(args[i+1].clone());
                                        handled = true;
                                        break;
                                    }
                                },
                                'h' => { print_help_and_exit(); },
                                'V' => { print_version_and_exit(); },
                                _ => {
                                    let msg = format!("error: unexpected argument '-{}' found\n\n  tip: to pass '-{}' as a value, use '-- -{}'\n\nUsage: executable [OPTIONS] [FILE]\n\nFor more information, try '--help'.\n", c, c, c);
                                    exit_with_error(&msg);
                                }
                            }
                        }
                        if handled {
                            // will process opt_name/val below
                        } else {
                            i+=1;
                            continue;
                        }
                    },
                    'd' | 's' | 'p' | 'i' => {
                        if !rest.is_empty() {
                            opt_name = Some(match first { 'd'=>"delimiter", 's'=>"style", 'p'=>"padding", 'i'=>"indent", _=>unreachable!() });
                            opt_val = Some(rest);
                        } else {
                            opt_name = Some(match first { 'd'=>"delimiter", 's'=>"style", 'p'=>"padding", 'i'=>"indent", _=>unreachable!() });
                            consumed_next = true;
                            if i+1 >= args.len() {
                                let msg = format!("error: a value is required for '-{} <{}>' but none was supplied\n\nFor more information, try '--help'.\n", first, first.to_uppercase());
                                exit_with_error(&msg);
                            }
                            opt_val = Some(args[i+1].clone());
                        }
                    },
                    _ => {
                        let msg = format!("error: unexpected argument '{}' found\n\nUsage: executable [OPTIONS] [FILE]\n\nFor more information, try '--help'.\n", arg);
                        exit_with_error(&msg);
                    }
                }
