        match std::fs::read(path) {
            Ok(b) => b,
            Err(e) => {
                eprintln!("csview: {}", e);
                std::process::exit(1);
            }
        }
    } else {
        let mut buf = Vec::new();
        use std::io::Read;
        std::io::stdin().lock().read_to_end(&mut buf).unwrap();
        buf
    };

    let data_slice: &[u8] = if data.starts_with(&[0xEF, 0xBB, 0xBF]) {
        &data[3..]
    } else {
        &data[..]
    };

