    }

    let has_header = header_cells_rendered.is_some();
    let has_body = !body.is_empty();

    let mut body_rows_rendered: Vec<Vec<String>> = Vec::new();
    for (idx, row) in body.iter().enumerate() {
        let mut cells = Vec::new();
        if include_number {
            let num = (idx+1).to_string();
            cells.push(render_cell(&num, number_width, padding, &body_align));
        }
        for (i, c) in row.iter().enumerate() {
            cells.push(render_cell(c, col_widths[i], padding, &body_align));
        }
        body_rows_rendered.push(cells);
    }

    let output: String = match style.as_str() {
        "none" => {
            let mut out = String::new();
            if let Some(cells) = header_cells_rendered.as_ref() {
                let line = indent_str.clone() + &cells.concat();
                out.push_str(&line);
                out.push('\n');
            }
            for cells in &body_rows_rendered {
                let line = indent_str.clone() + &cells.concat();
                out.push_str(&line);
                out.push('\n');
            }
            if out.is_empty() {
                if raw_is_empty && no_headers {
                } else {
                    out.push_str(&indent_str);
                    out.push('\n');
                }
            }
            out
        },
        "ascii2" => {
            let mut out = String::new();
            if let Some(cells) = header_cells_rendered.as_ref() {
                if cells.is_empty() {
                    out.push_str(&format!("{}  \n", indent_str));
                } else {
                    let row_inner = cells.join("|");
                    out.push_str(&indent_str);
                    out.push(' ');
                    out.push_str(&row_inner);
                    out.push(' ');
                    out.push('\n');
                }
            }
            if has_header && has_body {
                let sep_inner = combined_interiors.iter().map(|w| "-".repeat(*w)).collect::<Vec<_>>().join("+");
                out.push_str(&indent_str);
                out.push(' ');
                out.push_str(&sep_inner);
                out.push(' ');
                out.push('\n');
            }
            for cells in &body_rows_rendered {
                if cells.is_empty() {
                    out.push_str(&format!("{}  \n", indent_str));
                } else {
                    let row_inner = cells.join("|");
                    out.push_str(&indent_str);
                    out.push(' ');
                    out.push_str(&row_inner);
                    out.push(' ');
                    out.push('\n');
                }
            }
            if out.is_empty() {
                if raw_is_empty && no_headers {
                } else {
                    out.push_str(&format!("{}  \n", indent_str));
                }
            }
            out
        },
        "markdown" => {
            let mut out = String::new();
            if let Some(cells) = header_cells_rendered.as_ref() {
                if cells.is_empty() {
                    out.push_str(&format!("{}||\n", indent_str));
                } else {
                    let row_inner = cells.join("|");
                    out.push_str(&indent_str);
                    out.push('|');
                    out.push_str(&row_inner);
                    out.push('|');
                    out.push('\n');
                }
            }
            if has_header && has_body {
                let sep_inner = combined_interiors.iter().map(|w| "-".repeat(*w)).collect::<Vec<_>>().join("|");
                out.push_str(&indent_str);
                out.push('|');
                out.push_str(&sep_inner);
                out.push('|');
                out.push('\n');
            }
            for cells in &body_rows_rendered {
                if cells.is_empty() {
                    out.push_str(&format!("{}||\n", indent_str));
                } else {
                    let row_inner = cells.join("|");
                    out.push_str(&indent_str);
                    out.push('|');
                    out.push_str(&row_inner);
                    out.push('|');
                    out.push('\n');
                }
            }
            if out.is_empty() {
                if raw_is_empty && no_headers {
                } else {
                    out.push_str(&format!("{}||\n", indent_str));
                }
            }
            out
        },
        _ => {
            let (top_left, top_fill, top_join, top_right, mid_left, mid_fill, mid_join, mid_right, row_left, row_mid, row_right, bottom_left, bottom_fill, bottom_join, bottom_right) = match style.as_str() {
                "sharp" => ("┌","─","┬","┐","├","─","┼","┤","│","│","│","└","─","┴","┘"),
                "rounded" => ("╭","─","┬","╮","├","─","┼","┤","│","│","│","╰","─","┴","╯"),
                "reinforced" => ("┏","─","┬","┓","├","─","┼","┤","│","│","│","┗","─","┴","┛"),
                "ascii" => ("+","-","+","+","+","-","+","+","|","|","|","+","-","+","+"),
                "grid" => ("┌","─","┬","┐","├","─","┼","┤","│","│","│","└","─","┴","┘"),
                _ => ("┌","─","┬","┐","├","─","┼","┤","│","│","│","└","─","┴","┘"),
            };
            let mut out = String::new();
            if ncols_total == 0 {
                out.push_str(&build_border_line(&indent_str, top_left, top_fill, top_join, top_right, &combined_interiors));
                if has_header {
                    out.push_str(&format!("{}{}{}\n", indent_str, row_left, row_right));
                } else if has_body {
                    for _ in &body_rows_rendered {
                        out.push_str(&format!("{}{}{}\n", indent_str, row_left, row_right));
                    }
                } else {
                    if !no_headers {
                        out.push_str(&format!("{}{}{}\n", indent_str, row_left, row_right));
                    }
                }
                out.push_str(&build_border_line(&indent_str, bottom_left, bottom_fill, bottom_join, bottom_right, &combined_interiors));
                out
            } else {
                out.push_str(&build_border_line(&indent_str, top_left, top_fill, top_join, top_right, &combined_interiors));
                if let Some(cells) = header_cells_rendered.as_ref() {
                    let row_inner = cells.join(row_mid);
                    out.push_str(&indent_str);
                    out.push_str(row_left);
                    out.push_str(&row_inner);
                    out.push_str(row_right);
                    out.push('\n');
                }
                if has_header && has_body {
                    out.push_str(&build_border_line(&indent_str, mid_left, mid_fill, mid_join, mid_right, &combined_interiors));
                }
                for (idx, cells) in body_rows_rendered.iter().enumerate() {
                    let row_inner = cells.join(row_mid);
                    out.push_str(&indent_str);
                    out.push_str(row_left);
                    out.push_str(&row_inner);
                    out.push_str(row_right);
                    out.push('\n');
                    if style == "grid" && idx + 1 < body_rows_rendered.len() {
                        out.push_str(&build_border_line(&indent_str, mid_left, mid_fill, mid_join, mid_right, &combined_interiors));
                    }
                }
                out.push_str(&build_border_line(&indent_str, bottom_left, bottom_fill, bottom_join, bottom_right, &combined_interiors));
                out
            }
        }
    };

    if disable_pager {
        print!("{}", output);
    } else {
        let is_tty = unsafe { libc_isatty() };
        if is_tty {
            let pager = std::env::var("PAGER").unwrap_or_else(|_| "less".to_string());
            use std::process::{Command, Stdio};
            use std::io::Write;
            let mut cmd = Command::new(&pager);
            if pager.contains("less") {
